const r = $input.first()?.json || {};

if (r.error) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo eliminar el evento: ' + (r.error?.message || r.error) } } }];
}

if (r.violacion === 'not_found') {
  return [{ json: { statusCode: 404, body: { message: 'El evento no existe.' } } }];
}
if (r.violacion === 'is_system') {
  return [{ json: { statusCode: 403, body: { message: 'Este evento lo entrega el producto y no se puede eliminar. Si no se usa, se puede desactivar.' } } }];
}
if (r.violacion === 'has_implementations') {
  const n = Number(r.implementaciones || 0);
  return [{ json: { statusCode: 409, body: { message: `El evento tiene ${n} implementación(es) registrada(s). Hay que eliminarlas primero.` } } }];
}

return [{ json: { statusCode: 200, body: r.evento || { deleted: true } } }];
